const base = global.get('haBaseUrl') || 'http://127.0.0.1:8123';
const token = global.get('haToken') || '';
if (!token) {
    node.status({ fill: 'red', shape: 'ring', text: 'no HA token' });
    return null;
}
msg.url = base + '/api/states';
msg.method = 'GET';
msg.headers = { Authorization: 'Bearer ' + token };
return msg;

const lib = global.get('solarComputed');
if (!lib || !lib.computeSolarDerived) {
    node.status({ fill: 'red', shape: 'ring', text: 'no solarComputed lib' });
    return null;
}
if (!Array.isArray(msg.payload)) {
    node.status({ fill: 'red', shape: 'ring', text: 'bad states' });
    return null;
}
const d = lib.computeSolarDerived(msg.payload);
flow.set('solarComputedLast', d);
const k = d.ku_pwm_mppt_combined_est_w;
node.status({ fill: 'green', shape: 'dot', text: 'KU est ' + (k == null ? 'n/a' : k + ' W') });
msg.payload = d;
return msg;

const d = flow.get('solarComputedLast') || {};
function cell(label, val, unit) {
    const v = val == null ? 'Unavailable' : String(val) + (unit || '');
    return '<tr><td>' + label + '</td><td><strong>' + v + '</strong></td></tr>';
}
const rows = [
    cell('T2 MPPT W', d.t2_mppt_w, ' W'),
    cell('T2-KU jumper W', d.t2_ku_jumper_w, ' W'),
    cell('KU Victron MPPT 2+3 est W', d.ku_victron_mppt23_est_w, ' W'),
    cell('KU PWM+MPPT combined est W', d.ku_pwm_mppt_combined_est_w, ' W'),
    cell('KU PWM est W', d.ku_pwm_est_w, ' W'),
    cell('KU equal share (1/3) W', d.ku_charger_equal_share_w, ' W'),
    cell('EM16 A3 live W', d.em16_a3_live_w, ' W'),
];
msg.payload = '<!DOCTYPE html><html><head><meta charset="utf-8"><title>Solar computed</title>' +
'<style>body{font-family:sans-serif;background:#111;color:#eee;padding:1rem}' +
'table{border-collapse:collapse;width:100%;max-width:32rem}td{padding:0.5rem;border-bottom:1px solid #333}' +
'h1{font-size:1.1rem}p{color:#888;font-size:0.85rem}</style></head><body>' +
'<h1>Solar computed meters</h1><p>From HA device states only. Site solar in HA stays device tiles.</p>' +
'<table>' + rows.join('') + '</table></body></html>';
msg.headers = { 'Content-Type': 'text/html; charset=utf-8' };
return msg;
